// The settings fixtures are real-world files (fetched 2026-11-04):
//   - testdata/setup-java-settings.xml: what actions/setup-java writes for its defaults
//     (server-id github, GITHUB_ACTOR, GITHUB_TOKEN), as generated by generate() in
//     https://github.com/actions/setup-java/blob/main/src/auth.ts.
//   - testdata/mirror-guide-settings.xml: the "Advanced Mirror Specification" example of
//     https://maven.apache.org/guides/mini/guide-mirror-settings.html.

// hosts is a fake set of Maven repositories on any host: every request is routed to one
// httptest server and served by "host/path".
type hosts struct {
	t     *testing.T
	files map[string]string // host + path -> body
	moved map[string]string // host + path -> redirect target

	mu   sync.Mutex
	reqs map[string][]http.Header // host + path -> request headers
}

func newHosts(t *testing.T) (*hosts, *http.Client) {
	h := &hosts{t: t, files: map[string]string{}, moved: map[string]string{}, reqs: map[string][]http.Header{}}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		k := req.Header.Get("X-Test-Host") + req.URL.Path
		h.mu.Lock()
		h.reqs[k] = append(h.reqs[k], req.Header.Clone())
		h.mu.Unlock()
		if to, ok := h.moved[k]; ok {
			http.Redirect(w, req, to, http.StatusFound)
			return
		}
		body, ok := h.files[k]
		if !ok {
			http.NotFound(w, req)
			return
		}
		_, _ = w.Write([]byte(body))
	}))
	t.Cleanup(srv.Close)
	addr := srv.Listener.Addr().String()
	c := &http.Client{Transport: roundTripper(func(req *http.Request) (*http.Response, error) {
		r := req.Clone(req.Context())
		r.Header.Set("X-Test-Host", req.URL.Host)
		r.URL.Scheme, r.URL.Host = "http", addr
		return http.DefaultTransport.RoundTrip(r)
	})}
	return h, c
}

type roundTripper func(*http.Request) (*http.Response, error)

func (f roundTripper) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

// headers returns the headers of the requests to host+path.
func (h *hosts) headers(k string) []http.Header {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.reqs[k]
}

const libMeta = `<metadata><versioning><versions><version>1.0</version><version>2.0</version></versions></versioning></metadata>`

func env(m map[string]string) func(string) string { return func(k string) string { return m[k] } }

func writeFile(t *testing.T, p, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func urls(rs []repository) []string {
	out := make([]string, len(rs))
	for i, r := range rs {
		out[i] = r.id + "=" + r.url
	}
	return out
}

func TestParseSource(t *testing.T) {
	s := New(http.DefaultClient, nil, env(map[string]string{"DEPS_MAVEN_CENTRAL_URL": "https://mirror.example/m2"}))
	tests := []struct{ src, want string }{
		{"", "central=https://mirror.example/m2/"},
		{"central=https://repo.maven.apache.org/maven2/", "central=https://mirror.example/m2/"},
		{"https://repo.maven.apache.org/maven2", "=https://mirror.example/m2/"},
		{"corp=https://corp.example/m2 \n https://plain.example/r/", "corp=https://corp.example/m2/ =https://plain.example/r/"},
		{"https://q.example/r?a=b", "=https://q.example/r?a=b/"},
	}
	for _, tt := range tests {
		if got := strings.Join(urls(s.parseSource(tt.src)), " "); got != tt.want {
			t.Errorf("%q: %s, want %s", tt.src, got, tt.want)
		}
	}
}

func TestMatchMirrorOf(t *testing.T) {
	ext := repository{id: "repo1", url: "https://repo.example/m2/"}
	extHTTP := repository{id: "repo1", url: "http://repo.example/m2/"}
	local := repository{id: "repo1", url: "http://localhost:8081/m2/"}
	file := repository{id: "repo1", url: "file:///srv/m2/"}
	noID := repository{url: "https://repo.example/m2/"}
	tests := []struct {
		pattern string
		r       repository
		want    bool
	}{
		{"*", local, true},
		{"*", noID, true},
		{"repo1", ext, true},
		{"repo2", ext, false},
		{"central", repository{id: "central", url: Central}, true},
		{"repo2,repo1", ext, true},
		{"repo2,repo3", ext, false},
		{"*,!repo1", ext, false},
		{"!repo1,*", ext, false},
		{"*,!repo2", ext, true},
		{"!repo1, *", repository{id: "repo2", url: ext.url}, false}, // " *" is not a wildcard
		{"external:*", ext, true},
		{"external:*", noID, true},
		{"external:*", local, false},
		{"external:*", repository{id: "r", url: "http://127.0.0.1/m2/"}, false},
		{"external:*", file, false},
		{"external:*,!repo1", ext, false},
		{"external:http:*", extHTTP, true},
		{"external:http:*", ext, false},
		{"external:http:*", local, false},
		{"", noID, false},
		{"repo1", noID, false},
	}
	for _, tt := range tests {
		if got := matchMirrorOf(tt.pattern, tt.r); got != tt.want {
			t.Errorf("matchMirrorOf(%q, %s=%s) = %v", tt.pattern, tt.r.id, tt.r.url, got)
		}
	}
}

func TestMirrors(t *testing.T) {
	dir := t.TempDir()
	user := filepath.Join(dir, "settings.xml")
	writeFile(t, user, fixture(t, "mirror-guide-settings.xml"))
	h, c := newHosts(t)
	h.files["repo.mycompany.com/proxy/org/example/lib/maven-metadata.xml"] = libMeta
	s := New(c, nil, env(map[string]string{"DEPS_MAVEN_SETTINGS": user}))

	src := "foo=https://foo.example/repo/ local=http://localhost:8081/r/ corp=https://corp.example/m2/ central=https://repo.maven.apache.org/maven2/"
	d := dep.Dep{Manager: "maven", File: "pom.xml", Name: "org.example:lib", Source: src}
	repos, err := s.repositories(d, dir)
	if err != nil {
		t.Fatal(err)
	}
	// external:*,!foo mirrors corp and central onto one repository; foo has its own mirror;
	// localhost is not external.
	want := []string{"foo-repository=http://repo.mycompany.com/foo/", "local=http://localhost:8081/r/", "internal-repository=http://repo.mycompany.com/proxy/"}
	if got := urls(repos); !slices.Equal(got, want) {
		t.Errorf("repositories = %v, want %v", got, want)
	}
	rels, err := s.Releases(context.Background(), d, dir)
	if err != nil || !slices.Equal(versions(rels), []string{"1.0", "2.0"}) {
		t.Fatalf("Releases = %v, %v", versions(rels), err)
	}
	if n := len(h.headers("corp.example/m2/org/example/lib/maven-metadata.xml")); n != 0 {
		t.Errorf("mirrored repository requested %d times", n)
	}

	// Gradle ignores settings.xml.
	d.Manager = "gradle"
	if repos, _ := s.repositories(d, dir); repos[0].url != "https://foo.example/repo/" || len(repos) != 4 {
		t.Errorf("gradle repositories = %v", urls(repos))
	}
}

func TestServerAuth(t *testing.T) {
	root := t.TempDir()
	user := filepath.Join(root, "home", ".m2", "settings.xml")
	writeFile(t, user, fixture(t, "setup-java-settings.xml"))
	// In-repository settings with a header-authenticated server and a mirror needing auth.
	writeFile(t, filepath.Join(root, "repo", ".mvn", "settings.xml"), `<settings>
  <mirrors><mirror><id>corp</id><url>https://nexus.example/group</url><mirrorOf>legacy</mirrorOf></mirror></mirrors>
  <servers>
    <server><id>gitlab</id><configuration><httpHeaders><property><name>Private-Token</name><value>${CI_JOB_TOKEN}</value></property></httpHeaders></configuration></server>
    <server><id>corp</id><username>ci</username><password>${env.NEXUS_PASSWORD}</password></server>
    <server><id>legacy</id><username>never</username><password>used</password></server>
  </servers>
</settings>`)
	h, c := newHosts(t)
	const p = "org/example/lib/maven-metadata.xml"
	for _, host := range []string{"maven.pkg.github.com/o/r/", "gitlab.example/api/v4/packages/maven/", "nexus.example/group/", "repo.maven.apache.org/maven2/"} {
		h.files[host+p] = libMeta
	}
	s := New(c, nil, env(map[string]string{
		"HOME": filepath.Join(root, "home"), "GITHUB_ACTOR": "octocat", "GITHUB_TOKEN": "ghp_secret",
		"CI_JOB_TOKEN": "glpat-secret", "NEXUS_PASSWORD": "nexus-secret",
	}))
	d := dep.Dep{
		Manager: "maven", File: "repo/pom.xml", Name: "org.example:lib",
		Source: "github=https://maven.pkg.github.com/o/r/ gitlab=https://gitlab.example/api/v4/packages/maven/ legacy=https://legacy.example/m2/ central=https://repo.maven.apache.org/maven2/",
	}
	if _, err := s.Releases(context.Background(), d, filepath.Join(root, "repo")); err != nil {
		t.Fatal(err)
	}
	// Another pom under the same settings shares the cached lookups.
	sub := d
	sub.File = "repo/sub/pom.xml"
	if _, err := s.Releases(context.Background(), sub, filepath.Join(root, "repo", "sub")); err != nil {
		t.Fatal(err)
	}
	basic := func(user, pass string) string {
		r, _ := http.NewRequest(http.MethodGet, "/", http.NoBody)
		r.SetBasicAuth(user, pass)
		return r.Header.Get("Authorization")
	}
	tests := []struct{ host, auth, token string }{
		{"maven.pkg.github.com/o/r/", basic("octocat", "ghp_secret"), ""},
		{"gitlab.example/api/v4/packages/maven/", "", "glpat-secret"},
		{"nexus.example/group/", basic("ci", "nexus-secret"), ""}, // the mirror's server, not legacy's
		{"repo.maven.apache.org/maven2/", "", ""},
	}
	for _, tt := range tests {
		hs := h.headers(tt.host + p)
		if len(hs) != 1 {
			t.Fatalf("%s: %d requests", tt.host, len(hs))
		}
		if got := hs[0].Get("Authorization"); got != tt.auth {
			t.Errorf("%s: Authorization = %q, want %q", tt.host, got, tt.auth)
		}
		if got := hs[0].Get("Private-Token"); got != tt.token {
			t.Errorf("%s: Private-Token = %q, want %q", tt.host, got, tt.token)
		}
	}
	// The same repository without credentials (a gradle dep) is a separate lookup.
	gd := dep.Dep{Manager: "gradle", File: "build.gradle", Name: "org.example:lib", Source: "github=https://maven.pkg.github.com/o/r/"}
	if _, err := s.Releases(context.Background(), gd, root); err != nil {
		t.Fatal(err)
	}
	if hs := h.headers("maven.pkg.github.com/o/r/" + p); len(hs) != 2 || hs[1].Get("Authorization") != "" {
		t.Errorf("anonymous lookup: %v", hs)
	}
}

func TestHeadersDroppedOnCrossHostRedirect(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "settings.xml"), `<settings><servers><server><id>gl</id><username>u</username><password>p</password>
<configuration><httpHeaders><property><name>Private-Token</name><value>tok</value></property></httpHeaders></configuration></server></servers></settings>`)
	h, c := newHosts(t)
	h.moved["gl.example/m2/g/a/maven-metadata.xml"] = "https://cdn.example/blob/g-a"
	h.moved["gl.example/m2/g/b/maven-metadata.xml"] = "/m2/same-host"
	h.files["cdn.example/blob/g-a"] = libMeta
	h.files["gl.example/m2/same-host"] = libMeta
	s := New(c, nil, noenv)
	for _, name := range []string{"g:a", "g:b"} {
		d := dep.Dep{Manager: "maven", File: "pom.xml", Name: name, Source: "gl=https://gl.example/m2/"}
		if _, err := s.Releases(context.Background(), d, dir); err != nil {
			t.Fatal(err)
		}
	}
	if hs := h.headers("cdn.example/blob/g-a"); len(hs) != 1 || hs[0].Get("Private-Token") != "" || hs[0].Get("Authorization") != "" {
		t.Errorf("cross-host redirect kept credentials: %v", hs)
	}
	if hs := h.headers("gl.example/m2/same-host"); len(hs) != 1 || hs[0].Get("Private-Token") != "tok" {
		t.Errorf("same-host redirect lost the header: %v", hs)
	}
}

func TestSettingsPrecedenceAndProfiles(t *testing.T) {
	root := t.TempDir()
	repo := filepath.Join(root, "repo")
	user := filepath.Join(root, "user-settings.xml")
	writeFile(t, user, `<settings>
  <mirrors>
    <mirror><id>m</id><url>https://user-mirror.example/</url><mirrorOf>central</mirrorOf></mirror>
    <mirror><id>other</id><url>https://other-mirror.example/</url><mirrorOf>other</mirrorOf></mirror>
  </mirrors>
  <servers><server><id>m</id><username>user</username><password>user-pass</password></server></servers>
  <profiles>
    <profile><id>shared</id><repositories><repository><id>user-shared</id><url>https://user-shared.example/</url></repository></repositories></profile>
    <profile><id>byDefault</id><activation><activeByDefault>true</activeByDefault></activation>
      <repositories><repository><id>default</id><url>https://default.example/</url></repository></repositories>
      <pluginRepositories><pluginRepository><id>plugins</id><url>https://plugins.example/</url></pluginRepository></pluginRepositories></profile>
    <profile><id>inactive</id><repositories><repository><id>off</id><url>https://off.example/</url></repository></repositories></profile>
  </profiles>
  <activeProfiles><activeProfile>shared</activeProfile></activeProfiles>
</settings>`)
	writeFile(t, filepath.Join(repo, ".mvn", "settings.xml"), `<settings>
  <mirrors><mirror><id>m</id><url>https://repo-mirror.example/</url><mirrorOf>central</mirrorOf></mirror></mirrors>
  <servers><server><id>m</id><username>repo</username><password>repo-pass</password></server></servers>
  <profiles>
    <profile><id>shared</id><repositories><repository><id>repo-shared</id><url>https://repo-shared.example/</url></repository></repositories></profile>
    <profile><id>local</id><repositories><repository><id>local</id><url>https://local.example/</url></repository></repositories></profile>
  </profiles>
  <activeProfiles><activeProfile>local</activeProfile></activeProfiles>
</settings>`)
	// Above the scanned root of the plugin dep below: never read.
	writeFile(t, filepath.Join(root, "settings.xml"), `<settings><mirrors><mirror><id>outside</id><url>https://outside.example/</url><mirrorOf>*</mirrorOf></mirror></mirrors></settings>`)
	s := New(http.DefaultClient, nil, env(map[string]string{"DEPS_MAVEN_SETTINGS": user}))

	d := dep.Dep{Manager: "maven", File: "mod/pom.xml", Source: "own=https://own.example/ other=https://o.example/ central=" + Central}
	repos, err := s.repositories(d, filepath.Join(repo, "mod"))
	if err != nil {
		t.Fatal(err)
	}
	want := []string{
		"own=https://own.example/", "other=https://other-mirror.example/", // user-only mirror still applies
		"repo-shared=https://repo-shared.example/", "local=https://local.example/", "default=https://default.example/",
		"m=https://repo-mirror.example/",
	}
	if got := urls(repos); !slices.Equal(got, want) {
		t.Errorf("repositories =\n%v\nwant\n%v", got, want)
	}
	if a := repos[len(repos)-1].auth; a == nil || a.user != "repo" || a.pass != "repo-pass" {
		t.Errorf("central mirror auth = %+v", a)
	}

	// Plugins use the profiles' <pluginRepositories>; deps without in-repository settings the user's.
	// The scanned root is root/scan: root/settings.xml above it is never read.
	d = dep.Dep{Manager: "maven-wrapper", DepType: "build", File: "sub/pom.xml"}
	if repos, _ = s.repositories(d, filepath.Join(root, "scan", "sub")); !slices.Equal(urls(repos), []string{"plugins=https://plugins.example/", "m=https://user-mirror.example/"}) {
		t.Errorf("plugin repositories = %v", urls(repos))
	}
	if a := repos[1].auth; a == nil || a.user != "user" {
		t.Errorf("user auth = %+v", a)
	}
	if len(s.files) != 2 {
		t.Errorf("parsed %d settings files, want 2", len(s.files))
	}
}

func TestSettingsErrors(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "settings.xml"), `<settings><mirrors>`)
	s := New(http.DefaultClient, nil, noenv)
	d := dep.Dep{Manager: "maven", File: "pom.xml", Name: "g:a"}
	if _, err := s.Releases(context.Background(), d, dir); err == nil || !strings.Contains(err.Error(), "settings.xml") {
		t.Errorf("malformed settings: %v", err)
	}
}

func TestOpenArtifact(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, ".mvn", "settings.xml"), `<settings>
  <mirrors><mirror><id>nexus</id><url>https://nexus.example/group/</url><mirrorOf>central</mirrorOf></mirror></mirrors>
  <servers>
    <server><id>nexus</id><username>ci</username><password>nexus-secret</password></server>
    <server><id>corp</id><configuration><httpHeaders><property><name>Private-Token</name><value>tok</value></property></httpHeaders></configuration></server>
  </servers>
</settings>`)
	h, c := newHosts(t)
	const dist = "org/apache/maven/apache-maven/3.9.9/apache-maven-3.9.9-bin.zip"
	h.files["nexus.example/group/"+dist] = "zip"
	h.files["corp.example/m2/"+dist] = "corp zip"
	h.files["other.example/"+dist] = "other zip"
	s := New(c, nil, noenv)
	d := dep.Dep{Manager: "maven-wrapper", File: ".mvn/wrapper/maven-wrapper.properties", Name: "org.apache.maven:apache-maven",
		Source: "corp=https://corp.example/m2/ central=" + Central}
	if _, err := s.Releases(context.Background(), d, filepath.Join(dir, ".mvn", "wrapper")); err == nil {
		t.Fatal("Releases: no metadata served, want error") // still records the repositories
	}
	read := func(u string) string {
		t.Helper()
		rc, err := s.OpenArtifact(context.Background(), d, u)
		if err != nil {
			t.Fatalf("%s: %v", u, err)
		}
		defer rc.Close()
		b, _ := io.ReadAll(rc)
		return string(b)
	}
	basic := "Basic " + base64.StdEncoding.EncodeToString([]byte("ci:nexus-secret"))
	tests := []struct{ u, body, host, auth, token string }{
		{Central + dist, "zip", "nexus.example/group/", basic, ""},                        // declared Central, mirrored
		{"https://nexus.example/group/" + dist, "zip", "nexus.example/group/", basic, ""}, // already the mirror
		{"https://corp.example/m2/" + dist, "corp zip", "corp.example/m2/", "", "tok"},
		{"https://other.example/" + dist, "other zip", "other.example/", "", ""}, // unknown: anonymous
	}
	for i, tt := range tests {
		if got := read(tt.u); got != tt.body {
			t.Errorf("%s: body %q", tt.u, got)
		}
		hs := h.headers(tt.host + dist)
		last := hs[len(hs)-1]
		if last.Get("Authorization") != tt.auth || last.Get("Private-Token") != tt.token {
			t.Errorf("%d %s: headers %v", i, tt.u, last)
		}
	}
	_, err := s.OpenArtifact(context.Background(), d, Central+"missing.zip")
	if err == nil || err.Error() != "GET https://nexus.example/group/missing.zip: HTTP 404" {
		t.Errorf("missing: %v", err)
	}
}
